const state = await appStore.getState();
const root = appStore && typeof appStore === "object" ? null : null;

const shell = document.querySelector(".app-shell");
const form = shell.querySelector(".entry-form");
const dateInput = shell.querySelector("#f-date");
const typeSelect = shell.querySelector("#f-type");
const categoryInput = shell.querySelector("#f-category");
const amountInput = shell.querySelector("#f-amount");
const noteInput = shell.querySelector("#f-note");
const monthSelect = shell.querySelector("#f-month");
const formMessage = shell.querySelector('[data-role="form-message"]');
const listEl = shell.querySelector('[data-role="record-list"]');
const emptyEl = shell.querySelector('[data-role="empty-state"]');
const listHint = shell.querySelector('[data-role="list-hint"]');
const incomeEl = shell.querySelector('[data-role="total-income"]');
const expenseEl = shell.querySelector('[data-role="total-expense"]');
const balanceEl = shell.querySelector('[data-role="total-balance"]');
const countEl = shell.querySelector('[data-role="total-count"]');
const backdrop = document.querySelector('[data-role="dialog-backdrop"]');
const dialogText = backdrop.querySelector('[data-role="dialog-text"]');
const dialogConfirmBtn = backdrop.querySelector('[data-action="dialog-confirm"]');
const dialogCancelBtn = backdrop.querySelector('[data-action="dialog-cancel"]');

const TYPE_LABEL = { income: "收入", expense: "支出" };
const MONTH_ALL = "all";

let records = [];
let activeMonth = MONTH_ALL;
let pendingDeleteId = null;
let dialogResolver = null;

function pad2(n) {
  return String(n).padStart(2, "0");
}

function todayISO() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function normalizeRecord(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const type = src.type === "income" ? "income" : "expense";
  const amountNum = Number(src.amount);
  return {
    id: typeof src.id === "string" && src.id ? src.id : "rec-" + Math.random().toString(36).slice(2, 10),
    date: typeof src.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(src.date) ? src.date : todayISO(),
    type: type,
    category: typeof src.category === "string" ? src.category : "",
    amount: Number.isFinite(amountNum) ? amountNum : 0,
    note: typeof src.note === "string" ? src.note : ""
  };
}

function loadFromState(snapshot) {
  const src = snapshot && typeof snapshot === "object" ? snapshot : {};
  const list = Array.isArray(src.records) ? src.records : [];
  records = list.map(normalizeRecord);
}

function monthOf(dateStr) {
  return typeof dateStr === "string" && dateStr.length >= 7 ? dateStr.slice(0, 7) : "";
}

function formatMoney(value) {
  const n = Number.isFinite(value) ? value : 0;
  const sign = n < 0 ? "-" : "";
  return sign + "¥" + Math.abs(n).toFixed(2);
}

function formatMonthLabel(monthKey) {
  const parts = monthKey.split("-");
  if (parts.length !== 2) return monthKey;
  return parts[0] + " 年 " + Number(parts[1]) + " 月";
}

function getFilteredRecords() {
  if (activeMonth === MONTH_ALL) return records.slice();
  return records.filter(function (r) { return monthOf(r.date) === activeMonth; });
}

function computeTotals(list) {
  let income = 0;
  let expense = 0;
  for (let i = 0; i < list.length; i += 1) {
    const r = list[i];
    if (r.type === "income") income += r.amount;
    else expense += r.amount;
  }
  return {
    income: income,
    expense: expense,
    balance: income - expense,
    count: list.length
  };
}

function setFormMessage(text, kind) {
  formMessage.textContent = text || "";
  formMessage.classList.remove("is-error", "is-ok");
  if (kind === "error") formMessage.classList.add("is-error");
  else if (kind === "ok") formMessage.classList.add("is-ok");
}

function renderMonthOptions() {
  const months = [];
  const seen = {};
  for (let i = 0; i < records.length; i += 1) {
    const m = monthOf(records[i].date);
    if (m && !seen[m]) {
      seen[m] = true;
      months.push(m);
    }
  }
  months.sort(function (a, b) { return a < b ? 1 : a > b ? -1 : 0; });

  if (activeMonth !== MONTH_ALL && !seen[activeMonth]) {
    activeMonth = MONTH_ALL;
  }

  monthSelect.textContent = "";
  const allOpt = document.createElement("option");
  allOpt.value = MONTH_ALL;
  allOpt.textContent = "全部月份";
  monthSelect.appendChild(allOpt);

  for (let i = 0; i < months.length; i += 1) {
    const opt = document.createElement("option");
    opt.value = months[i];
    opt.textContent = formatMonthLabel(months[i]);
    monthSelect.appendChild(opt);
  }
  monthSelect.value = activeMonth;
}

function renderList(list) {
  listEl.textContent = "";
  if (list.length === 0) {
    emptyEl.hidden = false;
    emptyEl.textContent = records.length === 0
      ? "还没有任何记录，先在上方添加一笔吧。"
      : "当前月份没有记录，可切换月份或新增一笔。";
    return;
  }
  emptyEl.hidden = true;

  const sorted = list.slice().sort(function (a, b) {
    if (a.date === b.date) return 0;
    return a.date < b.date ? 1 : -1;
  });

  for (let i = 0; i < sorted.length; i += 1) {
    const r = sorted[i];
    const li = document.createElement("li");
    li.className = "record-item " + (r.type === "income" ? "is-income" : "is-expense");
    li.setAttribute("data-record-id", r.id);

    const main = document.createElement("div");
    main.className = "record-main";

    const line = document.createElement("div");
    line.className = "record-line";

    const dateSpan = document.createElement("span");
    dateSpan.className = "record-date";
    dateSpan.textContent = r.date;

    const tag = document.createElement("span");
    tag.className = "tag " + (r.type === "income" ? "tag-income" : "tag-expense");
    tag.textContent = TYPE_LABEL[r.type];

    const cat = document.createElement("span");
    cat.className = "record-category";
    cat.textContent = r.category ? r.category : "未分类";

    line.appendChild(dateSpan);
    line.appendChild(tag);
    line.appendChild(cat);
    main.appendChild(line);

    if (r.note) {
      const note = document.createElement("div");
      note.className = "record-note";
      note.textContent = r.note;
      main.appendChild(note);
    }

    const amount = document.createElement("span");
    amount.className = "record-amount " + (r.type === "income" ? "is-income" : "is-expense");
    amount.textContent = (r.type === "income" ? "+" : "-") + formatMoney(r.amount);

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn btn-mini";
    delBtn.setAttribute("data-action", "delete-record");
    delBtn.setAttribute("data-record-id", r.id);
    delBtn.textContent = "删除";

    li.appendChild(main);
    li.appendChild(amount);
    li.appendChild(delBtn);
    listEl.appendChild(li);
  }
}

function renderStats(totals) {
  incomeEl.textContent = formatMoney(totals.income);
  expenseEl.textContent = formatMoney(totals.expense);
  balanceEl.textContent = formatMoney(totals.balance);
  balanceEl.classList.toggle("is-negative", totals.balance < 0);
  countEl.textContent = String(totals.count);
}

function renderAll() {
  renderMonthOptions();
  const filtered = getFilteredRecords();
  const totals = computeTotals(filtered);
  renderStats(totals);
  renderList(filtered);

  const scope = activeMonth === MONTH_ALL ? "全部月份" : formatMonthLabel(activeMonth);
  listHint.textContent = scope + " · 共 " + totals.count + " 条";
}

function openConfirmDialog(text) {
  dialogText.textContent = text;
  backdrop.hidden = false;
  dialogCancelBtn.focus();
  return new Promise(function (resolve) {
    dialogResolver = resolve;
  });
}

function closeConfirmDialog(result) {
  backdrop.hidden = true;
  const resolver = dialogResolver;
  dialogResolver = null;
  if (resolver) resolver(result);
}

dialogConfirmBtn.addEventListener("click", function () {
  closeConfirmDialog(true);
});

dialogCancelBtn.addEventListener("click", function () {
  closeConfirmDialog(false);
});

backdrop.addEventListener("click", function (event) {
  if (event.target === backdrop) closeConfirmDialog(false);
});

document.addEventListener("keydown", function (event) {
  if (event.key === "Escape" && !backdrop.hidden) closeConfirmDialog(false);
});

async function persist(nextRecords) {
  const current = await appStore.getState();
  const base = current && typeof current === "object" ? current : {};
  const next = Object.assign({}, base, { records: nextRecords });
  await appStore.setState(next);
  const verify = await appStore.getState();
  loadFromState(verify);
}

form.addEventListener("submit", async function (event) {
  event.preventDefault();

  const date = dateInput.value;
  const type = typeSelect.value === "income" ? "income" : "expense";
  const category = categoryInput.value.trim();
  const amountRaw = amountInput.value.trim();
  const note = noteInput.value.trim();

  dateInput.classList.remove("invalid");
  categoryInput.classList.remove("invalid");
  amountInput.classList.remove("invalid");

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    dateInput.classList.add("invalid");
    setFormMessage("请选择有效的日期。", "error");
    dateInput.focus();
    return;
  }
  if (!category) {
    categoryInput.classList.add("invalid");
    setFormMessage("请填写分类。", "error");
    categoryInput.focus();
    return;
  }
  const amount = Number(amountRaw);
  if (!amountRaw || !Number.isFinite(amount) || amount <= 0) {
    amountInput.classList.add("invalid");
    setFormMessage("请输入大于 0 的金额。", "error");
    amountInput.focus();
    return;
  }

  const newRecord = {
    id: "rec-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 7),
    date: date,
    type: type,
    category: category,
    amount: Math.round(amount * 100) / 100,
    note: note
  };

  const nextRecords = records.concat([newRecord]);

  try {
    await persist(nextRecords);
  } catch (err) {
    setFormMessage("保存失败，请重试。输入内容已保留。", "error");
    return;
  }

  categoryInput.value = "";
  amountInput.value = "";
  noteInput.value = "";
  dateInput.value = todayISO();
  renderAll();
  setFormMessage("已保存：" + TYPE_LABEL[type] + " " + formatMoney(newRecord.amount) + "（" + newRecord.category + "）", "ok");
  categoryInput.focus();
});

shell.querySelector('[data-action="reset-form"]').addEventListener("click", function () {
  dateInput.value = todayISO();
  typeSelect.value = "expense";
  categoryInput.value = "";
  amountInput.value = "";
  noteInput.value = "";
  dateInput.classList.remove("invalid");
  categoryInput.classList.remove("invalid");
  amountInput.classList.remove("invalid");
  setFormMessage("表单已清空。", "");
  categoryInput.focus();
});

listEl.addEventListener("click", async function (event) {
  const btn = event.target.closest('[data-action="delete-record"]');
  if (!btn) return;

  const id = btn.getAttribute("data-record-id");
  const target = records.find(function (r) { return r.id === id; });
  if (!target) return;

  const label = target.date + " " + TYPE_LABEL[target.type] + " " + (target.category || "未分类") + " " + formatMoney(target.amount);
  const confirmed = await openConfirmDialog("确定要删除这条记录吗？\n" + label + "\n删除后无法恢复。");
  if (!confirmed) return;

  const remaining = records.filter(function (r) { return r.id !== id; });

  try {
    await persist(remaining);
  } catch (err) {
    setFormMessage("删除失败，请重试。", "error");
    return;
  }

  renderAll();
  setFormMessage("已删除记录：" + label, "ok");
});

monthSelect.addEventListener("change", function () {
  activeMonth = monthSelect.value || MONTH_ALL;
  renderAll();
});

dateInput.value = todayISO();
loadFromState(state);
renderAll();
setFormMessage("", "");

