:root {
  --bg-deep: #0f1c2e;
  --bg-mid: #16304d;
  --bg-soft: #1d3f63;
  --surface: rgba(255, 255, 255, 0.96);
  --surface-alt: #f2f6fb;
  --border: #d3dfec;
  --text-main: #14263c;
  --text-muted: #5c7189;
  --accent: #2f6fd0;
  --accent-dark: #1f4f9c;
  --income: #1a8f63;
  --income-soft: #e3f6ee;
  --expense: #c8452f;
  --expense-soft: #fdeae6;
  --danger: #c0392b;
  --shadow: 0 14px 34px rgba(6, 20, 38, 0.28);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  box-sizing: border-box;
  padding: 28px 18px 56px;
  background: linear-gradient(160deg, var(--bg-deep) 0%, var(--bg-mid) 46%, var(--bg-soft) 100%);
  color: var(--text-main);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.6;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 940px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  color: #eaf2fb;
  padding: 6px 4px 2px;
}

.app-title {
  margin: 0;
  font-size: 26px;
  letter-spacing: 1px;
  font-weight: 700;
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 14px;
  color: #a9c2dc;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
}

.panel-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.panel-title {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  color: var(--accent-dark);
  border-left: 4px solid var(--accent);
  padding-left: 10px;
}

.entry-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px 16px;
  margin-top: 14px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-wide {
  grid-column: 1 / -1;
}

.field-inline {
  flex-direction: row;
  align-items: center;
  gap: 8px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
}

.field input,
.field select {
  width: 100%;
  padding: 9px 11px;
  font-size: 15px;
  font-family: inherit;
  color: var(--text-main);
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: 9px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.field-inline select {
  width: auto;
  min-width: 150px;
}

.field input:focus,
.field select:focus {
  background: #ffffff;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(47, 111, 208, 0.18);
}

.field input.invalid {
  border-color: var(--danger);
  background: var(--expense-soft);
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.btn {
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  padding: 9px 18px;
  border-radius: 9px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.08s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent);
  color: #ffffff;
}

.btn-primary:hover {
  background: var(--accent-dark);
}

.btn-ghost {
  background: transparent;
  color: var(--accent-dark);
  border-color: var(--border);
}

.btn-ghost:hover {
  background: var(--surface-alt);
}

.btn-danger {
  background: var(--danger);
  color: #ffffff;
}

.btn-danger:hover {
  background: #a5311f;
}

.btn-mini {
  padding: 5px 12px;
  font-size: 13px;
  background: transparent;
  color: var(--danger);
  border-color: #e6c3bd;
}

.btn-mini:hover {
  background: var(--expense-soft);
}

.form-message {
  grid-column: 1 / -1;
  margin: 0;
  min-height: 20px;
  font-size: 13px;
  color: var(--text-muted);
}

.form-message.is-error {
  color: var(--danger);
  font-weight: 600;
}

.form-message.is-ok {
  color: var(--income);
  font-weight: 600;
}

.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 12px;
}

.stat {
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: 11px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 13px;
  color: var(--text-muted);
}

.stat-value {
  font-size: 20px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text-main);
}

.stat-income .stat-value {
  color: var(--income);
}

.stat-expense .stat-value {
  color: var(--expense);
}

.stat-balance {
  background: #eef4fd;
  border-color: #c8dbf5;
}

.stat-balance .stat-value {
  color: var(--accent-dark);
}

.stat-balance .stat-value.is-negative {
  color: var(--expense);
}

.list-hint {
  font-size: 13px;
  color: var(--text-muted);
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-left: 5px solid var(--accent);
  border-radius: 11px;
  background: #ffffff;
}

.record-item.is-income {
  border-left-color: var(--income);
}

.record-item.is-expense {
  border-left-color: var(--expense);
}

.record-main {
  flex: 1 1 240px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.record-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.record-date {
  font-size: 13px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.tag {
  font-size: 12px;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 999px;
  white-space: nowrap;
}

.tag-income {
  background: var(--income-soft);
  color: var(--income);
}

.tag-expense {
  background: var(--expense-soft);
  color: var(--expense);
}

.record-category {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-main);
  word-break: break-all;
}

.record-note {
  font-size: 13px;
  color: var(--text-muted);
  word-break: break-word;
}

.record-amount {
  font-size: 17px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.record-amount.is-income {
  color: var(--income);
}

.record-amount.is-expense {
  color: var(--expense);
}

.empty-state {
  margin: 0;
  padding: 22px 10px;
  text-align: center;
  color: var(--text-muted);
  font-size: 14px;
  background: var(--surface-alt);
  border: 1px dashed var(--border);
  border-radius: 11px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(8, 20, 36, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: #ffffff;
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: 0 20px 44px rgba(4, 14, 28, 0.4);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--text-main);
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-muted);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 520px) {
  #app {
    padding: 18px 12px 40px;
  }

  .panel {
    padding: 16px;
  }

  .record-amount {
    margin-left: auto;
  }
}
